script:
// =====================================
										// 1. ALWAYS DISABLE SYSTEM / COMPUTED FIELDS
										// =====================================
										disable Display_Name_Asset_Owner;
										disable Display_Name_Asset_Name;
										disable Display_Name_Asset_Type;
										disable Asset_ID;
										disable Status_Change_Date;
										disable Retirement_Date;
										disable Disposal_Date;
										disable Current_Site;
										disable Current_Custodian;
										disable Last_Transfer_Date;
										disable Last_Transfer_Reference;
										disable Asset_Status;
										disable Total_Service_Costs;
										disable Service_Cost_Per_Odometer;
										disable Total_Fuel_Costs;
										disable Fuel_Cost_Per_Odometer;
										disable Total_Labour_Costs;
										disable Labour_Cost_Per_Odometer;
										disable Total_Costs;
										disable Cost_Per_Odometer;
										// =====================================
										// 2. ALWAYS HIDE BACKEND / NON-USER FIELDS
										// =====================================
										hide Display_Name_Asset_Owner;
										hide Display_Name_Asset_Name;
										hide Display_Name_Asset_Type;
										hide Status_Change_Date;
										hide Retirement_Date;
										hide Disposal_Date;
										hide Current_Site;
										hide Current_Custodian;
										hide Last_Transfer_Date;
										hide Last_Transfer_Reference;
										hide Display_Name_Odometer_Unit_Of_Measure;
										// =====================================
										// 3. CONTROL AVAILABLE LISTS AND SUBFORMS
										// =====================================
										disable Available_Lists.Display_Name_Asset;
										disable Available_Lists.Display_Name_List;
										disable Available_Lists.Current_Site;
										disable Available_Lists.Current_Custodian;
										disable Available_Lists.Last_Transfer_Date;
										disable Available_Lists.Last_Transfer_Reference;
										hide Available_Lists.Display_Name_Asset;
										hide Available_Lists.Display_Name_List;
										hide Available_Lists.Current_Site;
										hide Available_Lists.Current_Custodian;
										hide Available_Lists.Last_Transfer_Date;
										hide Available_Lists.Last_Transfer_Reference;
										hide Available_Lists;
										hide Routine_Issues;
										hide Allowed_Emails;
										hide Store_Users;
										hide Transaction_Log;
										// =====================================
										// 4. LEASE SUMMARY AND OTHER HIDDEN FIELDS
										// =====================================
										hide Rental_Status;
										hide Current_Lease_Freedom_City_Management;
										hide Display_Name_Current_Tenant;
										hide Display_Name_Current_Lease;
										hide Lease_Start_Date;
										hide Lease_End_Date;
										hide Monthly_Rent;
										hide Occupancy_Status;
										hide Last_Handover_Date;
										hide Last_Take_Back_Date;
										hide Area;
										hide Volume;
										hide Email_Assigned;
										// =====================================
										// 5. CREATE MODE
										// =====================================
										if(input.ID == null)
										{
											hide Asset_ID;
											enable Odometer_Reading;
											enable Date_Time_Odometer_Read;
											enable Odometer_Unit_Of_Measure;
											if(input.Is_Purchased == true)
											{
												show Item;
												show Purchase_Cost;
											}
											else
											{
												hide Item;
												hide Purchase_Cost;
												input.Item = null;
												input.Purchase_Cost = null;
											}
										}
										// =====================================
										// 6. EDIT MODE
										// =====================================
										if(input.ID != null)
										{
											show Asset_ID;
											show Current_Custodian;
											show Current_Site;
											// Location and custody are maintained by transfers.
											disable Current_Custodian;
											disable Current_Site;
											disable Asset_Owner;
											disable Asset_Type;
											if(input.Is_Purchased == true)
											{
												show Item;
												show Purchase_Cost;
											}
											else
											{
												hide Item;
												hide Purchase_Cost;
												input.Item = null;
												input.Purchase_Cost = null;
											}
										}
										// =====================================
										// 7. ALWAYS BUILD DISPLAY NAME ASSET
										// =====================================
										if(input.Asset_Name != null && input.Asset_ID != null)
										{
											input.Display_Name_Asset_Name = input.Asset_Name + " - " + input.Asset_ID;
										}
										else if(input.Asset_Name != null)
										{
											input.Display_Name_Asset_Name = input.Asset_Name;
										}
										else
										{
											input.Display_Name_Asset_Name = "";
										}
										// =====================================
										// 8. ALWAYS BUILD DISPLAY NAME ASSET OWNER
										// =====================================
										if(input.Asset_Owner != null)
										{
											input.Display_Name_Asset_Owner = ifnull(input.Asset_Owner.Company_Name + " - " + input.Asset_Owner.Company_ID,"");
										}
										else
										{
											input.Display_Name_Asset_Owner = "";
										}
										// =====================================
										// 9. ALWAYS BUILD DISPLAY NAME ASSET TYPE
										// =====================================
										if(input.Asset_Type != null)
										{
											input.Display_Name_Asset_Type = ifnull(input.Asset_Type.Asset_Type_Name,"");
										}
										else
										{
											input.Display_Name_Asset_Type = "";
										}
										// =====================================
										// 10. BACKEND VISIBILITY AND EDIT RESTRICTIONS
										// =====================================
										if(input.ID == null)
										{
											hide Back_End;
											hide User_Name;
											hide User_Email;
											hide User_Role;
											hide Created_By_Name;
											hide Created_By_Email;
											hide Created_By_Time;
											hide Updated_By_Name;
											hide Updated_By_Email;
											hide Updated_By_Time;
										}
										else
										{
											//disable Notes;
											//disable Serial_Number;
											disable Asset_Images;
											disable Date_Time_Odometer_Read;
											disable Odometer_Reading;
											disable Odometer_Unit_Of_Measure;
											disable Asset_Name;
											show Back_End;
											show User_Name;
											show User_Email;
											show User_Role;
											show Created_By_Name;
											show Created_By_Email;
											show Created_By_Time;
											show Updated_By_Name;
											show Updated_By_Email;
											show Updated_By_Time;
											disable User_Name;
											disable User_Email;
											disable User_Role;
											disable Created_By_Name;
											disable Created_By_Email;
											disable Created_By_Time;
											disable Updated_By_Name;
											disable Updated_By_Email;
											disable Updated_By_Time;
										}

if(input.Asset_Name != null && input.Asset_ID != null)
										{
											input.Display_Name_Asset_Name = input.Asset_Name + " - " + input.Asset_ID;
										}

// ======================================
										// ASSET LIST - FULL VALIDATION
										// Created or Edited
										// ======================================
										// Asset Owner Required
										if(input.Asset_Owner == null)
										{
											alert "Asset Owner is required.";
											cancel submit;
										}
										// Asset Name Required
										if(input.Asset_Name == null || input.Asset_Name.trim() == "")
										{
											alert "Asset Name is required.";
											cancel submit;
										}
										// Asset Name No Duplicates
										existingAsset = Asset_List[ID != input.ID && Asset_Name == input.Asset_Name];
										if(existingAsset.count() > 0)
										{
											alert "Asset Name already exists. Please enter a unique Asset Name.";
											cancel submit;
										}
										// Asset Type Required
										if(input.Asset_Type == null)
										{
											alert "Asset Type is required.";
											cancel submit;
										}
										// Odometer Reading Required and >= 0
										if(input.Odometer_Reading == null)
										{
											alert "Odometer Reading is required.";
											cancel submit;
										}
										if(input.Odometer_Reading < 0)
										{
											alert "Odometer Reading must be greater than or equal to 0.";
											cancel submit;
										}
										// Odometer Unit of Measure Required
										if(input.Odometer_Unit_Of_Measure == null)
										{
											alert "Odometer Unit of Measure is required.";
											cancel submit;
										}
										// Date-Time Odometer Reading Required
										if(input.Date_Time_Odometer_Read == null)
										{
											alert "Date-Time Odometer Reading is required.";
											cancel submit;
										}
										// Reading time must not be in the future
										if(input.Date_Time_Odometer_Read > zoho.currenttime)
										{
											alert "Date-Time Odometer Reading cannot be in the future.";
											cancel submit;
										}
										// Asset Images Required
										if(input.Asset_Images == null)
										{
											alert "Asset Images is required.";
											cancel submit;
										}
										// ======================================
										// PURCHASE VALIDATION
										// ======================================
										if(input.Is_Purchased == true)
										{
											if(input.Item == null)
											{
												alert "Item is required when Is Purchased is checked.";
												cancel submit;
											}
											if(input.Purchase_Cost == null || input.Purchase_Cost <= 0)
											{
												alert "Purchase Cost is required and must be greater than 0 when Is Purchased is checked.";
												cancel submit;
											}
										}

q = ifnull(input.Quantity,0.0);
										r = ifnull(input.Rate,0.0);
										input.Line_Total = round(q * r,2);

q = ifnull(input.Quantity,0.0);
										r = ifnull(input.Rate,0.0);
										input.Line_Total = round(q * r,2);

errs = "";
										// 1. Quantity must be greater than 0
										if(input.Quantity != null && input.Quantity <= 0)
										{
											errs = errs + "\n• Quantity must be greater than 0.";
										}
										// 2. Rate cannot be negative
										if(input.Rate != null && input.Rate < 0)
										{
											errs = errs + "\n• Rate cannot be negative.";
										}
										// 3. Finalize Line_Total before save (authoritative math)
										q = ifnull(input.Quantity,0.0);
										r = ifnull(input.Rate,0.0);
										input.Line_Total = round(q * r,2);
										// 4. Stop if there are problems
										if(errs != "")
										{
											alert "Please fix the following:" + errs;
											cancel submit;
										}

rec = Asset_Transfer_Expense_Detail[ID == input.ID];
										q = ifnull(input.Quantity,0.0);
										r = ifnull(input.Rate,0.0);
										rec.Line_Total=round(q * r,2);

if(input.Asset != null)
										{
											all_vouchers = Asset_Transfer_Voucher[Asset == input.Asset];
											latest_voucher_id = null;
											latest_voucher_date = null;
											for each  v in all_vouchers
											{
												this_v_date = v.Transfer_Voucher_Date;
												this_v_id = v.ID;
												if(latest_voucher_date == null)
												{
													latest_voucher_date = this_v_date;
													latest_voucher_id = this_v_id;
												}
												else
												{
													if(this_v_date > latest_voucher_date)
													{
														latest_voucher_date = this_v_date;
														latest_voucher_id = this_v_id;
													}
													else if(this_v_date == latest_voucher_date)
													{
														if(this_v_id > latest_voucher_id)
														{
															latest_voucher_id = this_v_id;
															latest_voucher_date = this_v_date;
														}
													}
												}
											}
											should_update = false;
											if(latest_voucher_id != null && latest_voucher_id == input.ID)
											{
												should_update = true;
											}
											if(should_update)
											{
												asset_rec = Asset_List[ID == input.Asset];
												if(asset_rec.ID != null)
												{
													site_text = "";
													custodian_text = "";
													if(input.Site_To != null)
													{
														site_text = ifnull(input.Site_To.Asset_Name,"") + " - " + ifnull(input.Site_To.Asset_ID,"");
													}
													if(input.Custodian_To != null)
													{
														custodian_text = ifnull(input.Custodian_To.Employee_Name,"") + " - " + ifnull(input.Custodian_To.Employee_Number,"");
													}
													asset_rec.Current_Site=site_text;
													asset_rec.Current_Custodian=custodian_text;
													asset_rec.Last_Transfer_Date=input.Transfer_Voucher_Date;
													asset_rec.Last_Transfer_Reference=input.Display_Name_Asset_Transfer_Voucher;
												}
												avail_rows = Available_Lists[Asset == input.Asset];
												for each  a in avail_rows
												{
													a.Current_Site=input.Site_To;
													a.Current_Custodian=input.Custodian_To;
													a.Last_Transfer_Date=input.Transfer_Voucher_Date;
													a.Last_Transfer_Reference=input.Display_Name_Asset_Transfer_Voucher;
												}
											}
											else
											{
												info "This transfer voucher is older than the asset's current recorded location. Asset_List was not updated.";
											}
										}
										if(input.Movement_Expense_Details != null && input.Movement_Expense_Details.count() > 0)
										{
											source_text = "";
											asset_text = "";
											current_site_text = "";
											from_text = "";
											to_text = "";
											reference_text = "";
											if(input.Display_Name_Asset_Transfer_Voucher != null && input.Display_Name_Asset_Transfer_Voucher.trim() != "")
											{
												source_text = input.Display_Name_Asset_Transfer_Voucher + " - Asset Transfer Expense";
											}
											else
											{
												source_text = "Asset Transfer Expense";
											}
											if(input.Asset != null)
											{
												asset_name = ifnull(input.Asset.Asset_Name,"").trim();
												asset_number = ifnull(input.Asset.Asset_ID,"").trim();
												if(asset_name != "" && asset_number != "")
												{
													asset_text = asset_name + " - " + asset_number;
												}
												else if(asset_name != "")
												{
													asset_text = asset_name;
												}
												else
												{
													asset_text = asset_number;
												}
											}
											if(input.Site_From != null)
											{
												from_name = ifnull(input.Site_From.Asset_Name,"").trim();
												from_number = ifnull(input.Site_From.Asset_ID,"").trim();
												if(from_name != "" && from_number != "")
												{
													from_text = from_name + " - " + from_number;
												}
												else if(from_name != "")
												{
													from_text = from_name;
												}
												else
												{
													from_text = from_number;
												}
											}
											if(input.Site_To != null)
											{
												to_name = ifnull(input.Site_To.Asset_Name,"").trim();
												to_number = ifnull(input.Site_To.Asset_ID,"").trim();
												if(to_name != "" && to_number != "")
												{
													to_text = to_name + " - " + to_number;
												}
												else if(to_name != "")
												{
													to_text = to_name;
												}
												else
												{
													to_text = to_number;
												}
												current_site_text = to_text;
											}
											if(asset_text != "")
											{
												reference_text = asset_text;
											}
											if(from_text != "")
											{
												if(reference_text != "")
												{
													reference_text = reference_text + " from " + from_text;
												}
												else
												{
													reference_text = "From " + from_text;
												}
											}
											if(to_text != "")
											{
												if(reference_text != "")
												{
													reference_text = reference_text + " to " + to_text;
												}
												else
												{
													reference_text = "To " + to_text;
												}
											}
											details_date = zoho.currentdate;
											if(input.Transfer_Voucher_Date != null)
											{
												details_date = input.Transfer_Voucher_Date;
											}
											for each  exp_row in input.Movement_Expense_Details
											{
												if(exp_row.ID != null)
												{
													qty_val = ifnull(exp_row.Quantity,0.0);
													rate_val = ifnull(exp_row.Rate,0.0);
													line_total_val = round(ifnull(exp_row.Line_Total,0.0),2);
													if(line_total_val == 0)
													{
														line_total_val = round(qty_val * rate_val,2);
													}
													item_text = ifnull(exp_row.Item_Name,"").trim();
													expense_description = ifnull(exp_row.Description,"").trim();
													details_text = "";
													if(input.Display_Name_Asset_Transfer_Voucher != null && input.Display_Name_Asset_Transfer_Voucher.trim() != "")
													{
														details_text = "Asset Transfer: " + input.Display_Name_Asset_Transfer_Voucher.trim();
													}
													if(input.Transfer_Voucher_Date != null)
													{
														details_text = details_text + "\nTransfer Date: " + input.Transfer_Voucher_Date.toString("dd-MMM-yyyy");
													}
													if(asset_text != "")
													{
														details_text = details_text + "\nAsset: " + asset_text;
													}
													if(from_text != "")
													{
														details_text = details_text + "\nFrom: " + from_text;
													}
													if(to_text != "")
													{
														details_text = details_text + "\nTo: " + to_text;
													}
													if(item_text != "")
													{
														details_text = details_text + "\nExpense: " + item_text;
													}
													if(expense_description != "")
													{
														details_text = details_text + "\nDescription: " + expense_description;
													}
													existing_bd = Bill_Details[Asset_Transfer_Expense_Detail == exp_row.ID];
													if(existing_bd.count() > 0)
													{
														for each  bd in existing_bd
														{
															bd.Details_Date=details_date;
															bd.Source=source_text;
															bd.Reference=reference_text;
															bd.Asset_Transfer_Expense_Detail=exp_row.ID;
															bd.Display_Name_Item=item_text;
															bd.Description=details_text;
															bd.Quantity=qty_val;
															bd.Rate=rate_val;
															bd.Line_Total=line_total_val;
															bd.Account=asset_text;
															bd.Current_Site=current_site_text;
															info "==============================================";
															info "ASSET TRANSFER BILL DETAIL UPDATED";
															info "Expense Row ID: " + exp_row.ID;
															info "Bill Detail ID: " + bd.ID;
															info "Amount: " + line_total_val;
															info "==============================================";
															break;
														}
													}
													else
													{
														new_bill_detail_id = insert into Bill_Details
														[
															Details_Date=details_date
															Source=source_text
															Reference=reference_text
															Asset_Transfer_Expense_Detail=exp_row.ID
															Display_Name_Item=item_text
															Description=details_text
															Quantity=qty_val
															Rate=rate_val
															Line_Total=line_total_val
															Account=asset_text
															Current_Site=current_site_text
															Bill_Details_Status="Draft"
															Added_User=zoho.loginuser
														];
														info "==============================================";
														info "ASSET TRANSFER BILL DETAIL CREATED";
														info "Expense Row ID: " + exp_row.ID;
														info "Bill Detail ID: " + new_bill_detail_id;
														info "Amount: " + line_total_val;
														info "==============================================";
													}
												}
											}
										}

if(input.Asset != null)
										{
											remaining_vouchers = Asset_Transfer_Voucher[Asset == input.Asset];
											latest_id = null;
											latest_date = null;
											latest_site_to = null;
											latest_custodian_to = null;
											latest_ref = null;
											for each  v in remaining_vouchers
											{
												this_id = v.ID;
												this_date = v.Transfer_Voucher_Date;
												if(latest_date == null)
												{
													latest_date = this_date;
													latest_id = this_id;
													latest_site_to = v.Site_To;
													latest_custodian_to = v.Custodian_To;
													latest_ref = v.Display_Name_Asset_Transfer_Voucher;
												}
												else
												{
													if(this_date > latest_date)
													{
														latest_date = this_date;
														latest_id = this_id;
														latest_site_to = v.Site_To;
														latest_custodian_to = v.Custodian_To;
														latest_ref = v.Display_Name_Asset_Transfer_Voucher;
													}
													else if(this_date == latest_date)
													{
														if(this_id > latest_id)
														{
															latest_date = this_date;
															latest_id = this_id;
															latest_site_to = v.Site_To;
															latest_custodian_to = v.Custodian_To;
															latest_ref = v.Display_Name_Asset_Transfer_Voucher;
														}
													}
												}
											}
											if(latest_id != null)
											{
												site_text = "";
												custodian_text = "";
												if(latest_site_to != null)
												{
													site_text = ifnull(latest_site_to.Asset_Name,"") + " - " + ifnull(latest_site_to.Asset_ID,"");
												}
												if(latest_custodian_to != null)
												{
													custodian_text = ifnull(latest_custodian_to.Employee_Name,"") + " - " + ifnull(latest_custodian_to.Employee_Number,"");
												}
												asset_rec = Asset_List[ID == input.Asset];
												if(asset_rec.ID != null)
												{
													asset_rec.Current_Site=site_text;
													asset_rec.Current_Custodian=custodian_text;
													asset_rec.Last_Transfer_Date=latest_date;
													asset_rec.Last_Transfer_Reference=latest_ref;
												}
												avail_rows = Available_Lists[Asset == input.Asset];
												for each  a in avail_rows
												{
													a.Current_Site=latest_site_to;
													a.Current_Custodian=latest_custodian_to;
													a.Last_Transfer_Date=latest_date;
													a.Last_Transfer_Reference=latest_ref;
												}
											}
