										input.Service_Cost = round(services_total,2);
										// =====================================================
										// 5. PROCESS FINISHED, NON-CANCELLED REPORTS
										// =====================================================
										if(input.Cancel_Voucher != true && time_ok == true && input.Drager_Work_Report_Status == "Loaded" || input.Drager_Work_Report_Status == "Completed")
										{
											if(employee_display != "")
											{
												employee_lookup_result = employee_management.employee.get_employee_by_display_name(employee_display);
												if(employee_lookup_result != null)
												{
													if(ifnull(employee_lookup_result.get("ok"),false) == true)
													{
														employee_id = employee_lookup_result.get("employee_id");
													}
													else
													{
														info ifnull(employee_lookup_result.get("message"),"Employee lookup failed.");
													}
												}
											}
											if(employee_id == null)
											{
												delivered_processing_ok = false;
