											month_text = work_date.getMonth().toString();
											if(work_date.getMonth() < 10)
											{
												month_text = "0" + month_text;
											}
											month_start = ("01-" + month_text + "-" + work_date.getYear().toString()).toDate("dd-MM-yyyy");
											next_month_start = month_start.addMonth(1);
											month_reports = Drager_Work_Report[Display_Name_Employee == employee_display && Time_Start >= month_start && Time_Start < next_month_start && Cancel_Voucher != true];
											for each  report_rec in month_reports
											{
												report_services_total = 0.0;
												for each  service_row in report_rec.Services
												{
													report_services_total = report_services_total + round(ifnull(service_row.Quantity,0.0) * ifnull(service_row.Rate,0.0),2);
												}
												// Use the current input's total for the current report.
												if(report_rec.ID == input.ID)
												{
													report_services_total = input.Service_Cost;
													input.Labour_Cost = ifnull(report_rec.Labour_Cost,0.0);
												}
												report_rec.Service_Cost=round(report_services_total,2);
												report_total = round(report_services_total + ifnull(report_rec.Fuel_Cost,0.0) + ifnull(report_rec.Labour_Cost,0.0),2);
												report_rec.Line_Total=report_total;
												report_hours = 0.0;
												if(report_rec.Time_Start != null && report_rec.Time_End != null)
												{
													report_millis = report_rec.Time_End.toLong() - report_rec.Time_Start.toLong();
													if(report_millis > 0)
													{
														report_hours = report_millis / 3600000.0;
													}
												}
												if(report_hours > 0)
												{
													report_rec.Cost_Per_Odometer=round(report_total / report_hours,2);
												}
												else
												{
													report_rec.Cost_Per_Odometer=0.0;
												}
											}
										}
										// =====================================================
										// 9. CURRENT REPORT TOTAL
										// ALSO RUNS IF EMPLOYEE LOOKUP FAILS
										// =====================================================
										input.Line_Total = round(ifnull(input.Service_Cost,0.0) + ifnull(input.Fuel_Cost,0.0) + ifnull(input.Labour_Cost,0.0),2);
										if(exact_hours > 0)
										{
											input.Cost_Per_Odometer = round(input.Line_Total / exact_hours,2);
										}
										else
										{
											input.Cost_Per_Odometer = 0.0;
										}
										if(delivered_processing_ok == false)
										{
											info "Report totals calculated, but employee or billing processing encountered an error. Review the messages above.";
										}
										info "===== DRAGER WORK REPORT FINALIZE END =====";

if(row.Bill != null)
										{
											bill_rec = Bill[ID == row.Bill];
											if(bill_rec.ID != null)
											{
